import{_ as e,o as a,c as r,aj as s}from"./chunks/framework.BwH0p-pt.js";const u=JSON.parse('{"title":"Ready-made Templates","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/passport/presets.md","filePath":"2.1/passport/presets.md","lastUpdated":1788942616000}'),i={name:"2.1/passport/presets.md"};function o(n,t,l,d,p,h){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="ready-made-templates" tabindex="-1">Ready-made Templates <a class="header-anchor" href="#ready-made-templates" aria-label="Permalink to &quot;Ready-made Templates&quot;">​</a></h1><p>UnoPim ships two passport templates so you start from a regulation&#39;s field list instead of a blank page. They are installed on demand, and once installed they are ordinary templates — rename them, drop fields, add your own.</p><table tabindex="0"><thead><tr><th>Preset</th><th>Covers</th><th>Fields</th></tr></thead><tbody><tr><td><strong>EU Battery Passport</strong></td><td>EU Battery Regulation 2023/1542, Annex XIII — mandatory from <strong>18 February 2027</strong> for EV, LMT and industrial batteries above 2 kWh</td><td>26, of which 13 required</td></tr><tr><td><strong>EU ESPR (general)</strong></td><td>The general ESPR field list — a sensible starting point for textiles, electronics and other categories awaiting their delegated act</td><td>23</td></tr></tbody></table><h2 id="install-a-preset" tabindex="-1">Install a preset <a class="header-anchor" href="#install-a-preset" aria-label="Permalink to &quot;Install a preset&quot;">​</a></h2><p>Ask your developer or hosting team to run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:passport:install-preset</span></span></code></pre></div><p>Or one at a time:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unopim:passport:install-preset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --preset=battery</span></span></code></pre></div><p>The command is safe to re-run: a template that already exists is left untouched, so your edits are never overwritten.</p><h2 id="what-arrives-and-what-you-still-do" tabindex="-1">What arrives, and what you still do <a class="header-anchor" href="#what-arrives-and-what-you-still-do" aria-label="Permalink to &quot;What arrives, and what you still do&quot;">​</a></h2><p>An installed preset is deliberately <strong>inert</strong>:</p><ul><li>it is bound to <strong>no attribute family</strong>, so no product publishes because you installed it;</li><li>every field is <strong>unsourced</strong>, so nothing has been guessed about where your data lives.</li></ul><p>Your job is the mapping:</p><ol><li>Open <strong>Catalog → Passports → Templates</strong> and edit the preset.</li><li>Under <strong>Applies To</strong>, pick the families it covers.</li><li>For each field, choose the attribute that holds the value — or switch the field to a <strong>fixed value</strong> where the text is the same for every product.</li><li>Watch the readiness counter until every required field is sourced.</li><li>Publish from the product.</li></ol><div class="tip custom-block"><p class="custom-block-title">Nothing to map a field to?</p><p>Create the attribute the normal way (<strong>Catalog → Attributes</strong>), add it to the family, then point the field at it. Passport fields never store product data themselves — that stays in your attributes, where imports, history and translations already work.</p></div><h2 id="the-battery-preset-in-detail" tabindex="-1">The battery preset in detail <a class="header-anchor" href="#the-battery-preset-in-detail" aria-label="Permalink to &quot;The battery preset in detail&quot;">​</a></h2><p>Sections follow Annex XIII rather than the general list:</p><table tabindex="0"><thead><tr><th>Section</th><th>Contains</th></tr></thead><tbody><tr><td><strong>Battery Identity</strong></td><td>Unique battery identifier (GTIN role), manufacturer, category, date and place of manufacture, batch and model</td></tr><tr><td><strong>Performance and Durability</strong></td><td>Rated capacity, nominal voltage, weight, expected lifetime, cycle life, state of health <em>(operator)</em></td></tr><tr><td><strong>Materials and Footprint</strong></td><td>Chemistry, hazardous substances, carbon footprint, recycled cobalt / lithium / nickel / lead shares</td></tr><tr><td><strong>Safety and Circularity</strong></td><td>Safety measures, collection and recycling, dismantling information <em>(operator)</em>, supply-chain due diligence <em>(operator)</em></td></tr><tr><td><strong>Compliance Evidence</strong></td><td>EU declaration of conformity <em>(authority)</em>, test reports <em>(authority)</em></td></tr></tbody></table><p>Fields marked <em>(operator)</em> or <em>(authority)</em> never appear on the consumer page — they are reachable only through the signed links on the product&#39;s passport card. That mirrors the regulation: a recycler needs the dismantling sequence, a shopper does not.</p><h2 id="your-own-product-group" tabindex="-1">Your own product group <a class="header-anchor" href="#your-own-product-group" aria-label="Permalink to &quot;Your own product group&quot;">​</a></h2><p>Presets are configuration, so a developer can add a preset for your category — textiles, tyres, construction products — and it appears in the same install command. See the developer documentation for the shape of a preset definition.</p>',21)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
